+const story = {
+  groups: [
+    {
+      id: "login",
+      title: "Login route",
+      part: "Session cookie",
+      suggestedOrder: 1,
+      dependsOn: ["cookie"],
+    },
+    {
+      id: "cookie",
+      title: "Session cookie helper",
+      part: "Session cookie",
+      suggestedOrder: 0,
+    },
+    {
+      id: "docs",
+      title: "README wording",
+      part: "README",
+      suggestedOrder: 2,
+    },
+  ],
+};
+
+function takeShift(
+  shift: typeof shiftStorySelection,
+  selection: Selection,
+  delta: number,
+): Selection | undefined {
+  let next: Selection | undefined;
+  shift(story, selection, (value) => {
+    next = value;
+  }, delta);
+  return next;
+}
+
+describe("story and part selection", () => {
+  it("orders the stack by dependsOn inside each part", () => {
+    const ids = selectionStack({ groups: story.groups, unassigned: { hunkCount: 0 } })
+      .filter((item): item is { kind: "group"; id: string } => item.kind === "group")
+      .map((item) => item.id);
+    assert.deepEqual(ids, ["cookie", "login", "docs"]);
+  });
+
+  it("stays inside one part for [ and ]", () => {
+    assert.deepEqual(takeShift(shiftStorySelection, { kind: "overview" }, 1), { kind: "group", id: "cookie" });
+    assert.equal(takeShift(shiftStorySelection, { kind: "overview" }, -1), undefined);
+    assert.deepEqual(takeShift(shiftStorySelection, { kind: "group", id: "cookie" }, 1), { kind: "group", id: "login" });
+    assert.equal(takeShift(shiftStorySelection, { kind: "group", id: "login" }, 1), undefined);
+    assert.deepEqual(takeShift(shiftStorySelection, { kind: "group", id: "login" }, -1), { kind: "group", id: "cookie" });
+    assert.equal(takeShift(shiftStorySelection, { kind: "group", id: "cookie" }, -1), undefined);
+  });
+
+  it("moves between parts with { and }", () => {
+    assert.deepEqual(takeShift(shiftPartSelection, { kind: "overview" }, 1), { kind: "group", id: "cookie" });
+    assert.deepEqual(takeShift(shiftPartSelection, { kind: "group", id: "login" }, 1), { kind: "group", id: "docs" });
+    assert.deepEqual(takeShift(shiftPartSelection, { kind: "group", id: "docs" }, 1), { kind: "group", id: "cookie" });
+    assert.deepEqual(takeShift(shiftPartSelection, { kind: "group", id: "docs" }, -1), { kind: "group", id: "cookie" });
+  });
+
+  it("does nothing on unassigned", () => {
+    assert.equal(takeShift(shiftStorySelection, { kind: "unassigned" }, 1), undefined);
+    assert.equal(takeShift(shiftPartSelection, { kind: "unassigned" }, 1), undefined);
+  });
+});
